/**
 * @param {number} num
 * @param {number} sum
 * @return {string}
 */
var maxSumOfSquares = function(num, sum) {
    if (sum <= 0 || sum > num * 9) return '';

    let res = '';

    for (let i = 1; i <= num; i++) {
        let next = Math.min(sum, 9);
        res += next;
        sum -= next;
    }

    return res;
};

/**
 * @param {number} num
 * @param {number} sum
 * @return {string}
 */
var maxSumOfSquares = function(num, sum) {
    if (sum <= 0 || sum > num * 9) return '';

    const times = Math.floor(sum / 9);

    return '9'.repeat(times) + (sum % 9) + '0'.repeat(num - times - 1);
};

/**
 * @param {number} num
 * @param {number} sum
 * @return {string}
 */
var maxSumOfSquares = function(num, sum) {
    if (sum <= 0 || sum > num * 9) return '';

    const nines = Math.floor(sum / 9);
    const remainder = nines < num ? (sum % 9).toString() : '';
    const zeros = num - nines - remainder.length;

    return '9'.repeat(nines) + remainder + '0'.repeat(zeros);
};
